#!/usr/bin/env python3

import rclpy
from rclpy.node import Node
from eai_manipulator_msgs.msg import WarnAndErrorInfo
from std_msgs.msg import Header
import time


class TestDedupPublisher(Node):
    """测试去重功能的发布者节点"""

    def __init__(self):
        super().__init__('test_dedup_publisher')
        
        # 创建发布者
        self.publisher = self.create_publisher(
            WarnAndErrorInfo,
            '/manipulator/warn_and_error_info',
            10
        )
        
        # 创建定时器，每秒发送一次测试消息
        self.timer = self.create_timer(0.5, self.publish_test_message)
        
        self.get_logger().info('测试发布者已启动，将发送重复消息测试去重功能')

    def publish_test_message(self):
        """发布测试消息"""
        msg = WarnAndErrorInfo()
        msg.header = Header()
        msg.header.stamp = self.get_clock().now().to_msg()
        msg.header.frame_id = ""
        
        # 发送相同的消息来测试去重
        msg.level = "warning"
        msg.code = 1001
        msg.source = "test_controller"
        msg.info = "这是一个测试警告消息"
        
        self.publisher.publish(msg)
        self.get_logger().info(f'已发送测试消息: {msg.info}')


def main(args=None):
    """主函数"""
    rclpy.init(args=args)
    
    # 创建测试发布节点
    test_publisher = TestDedupPublisher()
    
    try:
        # 运行10秒后停止
        rclpy.spin_once(test_publisher, timeout_sec=10.0)
    except KeyboardInterrupt:
        pass
    finally:
        # 清理资源
        test_publisher.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
